// Example: {"i18n":{"zh-CN":{"caption":"代码编辑工作区"}},"sourceLocale":"zh-CN","theme":"dark"}
type ScreenshotUpdate struct {
	// I18n Example: {"zh-CN":{"caption":"代码编辑工作区"}}
	I18n *ScreenshotI18nMap `json:"i18n,omitempty"`

	// SourceLocale Supported language; without locale, match Accept-Language by q value and ultimately default to en-US.
	//
	// Example: en-US
	SourceLocale *Locale `json:"sourceLocale,omitempty"`

	// Theme Example: dark
	Theme *ScreenshotUpdateTheme `json:"theme,omitempty"`
}

// ScreenshotUpdateTheme Example: dark
type ScreenshotUpdateTheme string

